import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Card from '../components/Card';

function ConfirmSchedule() {
  const [assignments, setAssignments] = useState([]);

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    const res = await api.get('/assignments.php?status=pending');
    setAssignments(res.data || []);
  };

  const confirm = async (id) => {
    await api.post('/confirm.php', { assignment_id: id, status: 'confirmed' });
    loadData();
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <h1>Confirmar Presenca</h1>
      {assignments.length === 0 ? (
        <p>Nenhuma escala pendente.</p>
      ) : (
        assignments.map(a => (
          <Card key={a.id} style={{ marginBottom: 10 }}>
            <p><strong>{a.volunteer_name}</strong> - {a.shift_name}</p>
            <p>{a.date}</p>
            <button onClick={() => confirm(a.id)}>Confirmar</button>
          </Card>
        ))
      )}
    </div>
  );
}
export default ConfirmSchedule;
